def __init__(self, frame, channel=0, iface=None):
    self.frame = frame
    self.bssid = None
    self.ssid = None
    self.signal_strength = 0
    self.channel = channel
    self.iface = iface
    self.frame_bytes = len(frame)

    # DS = Distribution System; wired infrastructure connecting multiple BSSs to form an ESS
    # Needed to determine the meanings of addr1-4
    to_ds = frame.FCfield & Dot11Frame.TO_DS != 0
    from_ds = frame.FCfield & Dot11Frame.FROM_DS != 0
    if to_ds and from_ds:
        self.dst = frame.addr3
        self.src = frame.addr4
        self.macs = {frame.addr1, frame.addr2, frame.addr3, frame.addr4}
    elif to_ds:
        self.src = frame.addr2
        self.dst = frame.addr3
        self.bssid = frame.addr1
        self.macs = {frame.addr2, frame.addr3}
    elif from_ds:
        self.src = frame.addr3
        self.dst = frame.addr1
        self.bssid = frame.addr2
        self.macs = {frame.addr1, frame.addr3}
    else:
        self.dst = frame.addr1
        self.src = frame.addr2
        self.bssid = frame.addr3
        self.macs = {frame.addr1, frame.addr2}

    if (frame.haslayer(scapy.Dot11Elt) and
            (frame.haslayer(scapy.Dot11Beacon) or frame.haslayer(scapy.Dot11ProbeResp))):

        try:
            self.ssid = frame[scapy.Dot11Elt].info.decode().replace('\x00', '[NULL]')
        except UnicodeDecodeError:
            # Only seems to happen on macOS - probably some pcap decoding bug
            self.ssid = None
            #print('Error decoding ssid: {}'.format(frame[scapy.Dot11Elt].info))

    if frame.haslayer(scapy.RadioTap):
        try:
            self.signal_strength = frame[scapy.RadioTap].dbm_antsignal
        except AttributeError:
            try:
                self.signal_strength = -(256-ord(frame.notdecoded[-4:-3]))
            except Exception:
                self.signal_strength = -257

def load_from_file(file_path):
    """Factory function to load a Dot11Map from file_path provided."""
    with open(file_path, 'r') as f:
        yaml_data = f.read()

    yaml = ruamel.yaml.YAML(typ='safe')
    map_data = yaml.load(yaml_data)

    # If file is empty, return empty map
    if not map_data:
        return Dot11Map()

    bssids_associated_with_ssids = set()
    ssid_to_access_point = {}
    access_points = {}
    devices = {}

    for ssid, ssid_entry in map_data.items():
        if ssid == '~unassociated_devices':
            # ~unassociated_devices is not an SSID, but a special name to denote the list of devices
            # not associated with any network, so it needs to be processed differently.
            for mac, dev_node in ssid_entry.items():
                dev_node.pop('bytes')
                dev_node['frames_out'] = []
                dev_node['frames_in'] = []
                devices[mac] = dev_node
            continue

        unknown_ssid = ssid.startswith('unknown_ssid_')

        for bssid, ap_node in ssid_entry.items():
            if not unknown_ssid:
                bssids_associated_with_ssids |= {bssid}

            # Clean up access_point nodes
            ap_node = {k: v for k, v in ap_node.items() if k not in {'bssid', 'ssid', 'bytes'}}

            # We serialize by reducing the list of frames to a summation of the bytes, but loading back,
            # we replace that with an empty list. This means frames data is intentionally lost in serialize/load.
            ap_node['frames'] = []
            ap_node['channels'] = set(ap_node['channels'])

            if ssid not in ssid_to_access_point:
                ssid_to_access_point[ssid] = {bssid}
            else:
                ssid_to_access_point[ssid] |= {bssid}

            access_points[bssid] = ap_node

            for mac, dev_node in ap_node['devices'].items():
                dev_node.pop('bytes')
                dev_node['frames_out'] = []
                dev_node['frames_in'] = []
                devices[mac] = dev_node

            ap_node['devices'] = set([mac for mac in ap_node.pop('devices').keys()])

    dot11_map = Dot11Map({
        'bssids_associated_with_ssids': bssids_associated_with_ssids,
        'ssid_to_access_point': ssid_to_access_point,
        'access_points': access_points,
        'devices': devices
    })
    return dot11_map

