def trim_frames_to_window(frames, window, now=None):
    if not now:
        now = time.time()
    oldest_time_in_window = now - window
    oldest_in_window = -1  # Assume everything is in the window
    for index, frame in enumerate(frames):
        if frame[0] >= oldest_time_in_window:
            oldest_in_window = index
            break
    return frames[oldest_in_window:]

def add_frame(self, frame):
    with self.lock:
        # Update Access Point data
        if frame.bssid:
            self.update_access_point(frame.bssid, frame)

        # Update Device data
        for mac in frame.macs - {frame.bssid}:
            self.update_device(mac, frame)

        # Enrich the frame by adding the ssid if not already there and if we know it
        if not frame.ssid and frame.bssid in self.access_points:
            ssid = self.access_points[frame.bssid].get('ssid', None)
            if ssid:
                frame.ssid = ssid

        # TODO: Make sure beacons add 1 to frame counts (so that if looking for a threshold of 1 bytes they show up)

def update_access_point(self, bssid, frame):
    if bssid in MACS_TO_IGNORE:
        return

    if bssid not in self.access_points:
        ap_node = {'bssid': bssid,
                   'ssid': frame.ssid,
                   'vendor': self.mac_vendor_db.lookup(bssid),
                   'channels': {frame.channel},
                   'devices': set(),
                   'frames': []}
        self.access_points[bssid] = ap_node

    else:
        ap_node = self.access_points[frame.bssid]

    # Associate with ssid if ssid available
    if frame.ssid:
        if frame.ssid in self.ssid_to_access_point:
            self.ssid_to_access_point[frame.ssid] |= {bssid}
        else:
            self.ssid_to_access_point[frame.ssid] = {bssid}

        self.bssids_associated_with_ssids |= {bssid}

        # Make sure we didn't previously categorize this as an unknown_ssid
        missing_ssid_name = 'unknown_ssid_{}'.format(bssid)
        if missing_ssid_name in self.ssid_to_access_point:
            self.ssid_to_access_point[frame.ssid] |= self.ssid_to_access_point.pop(missing_ssid_name)
    elif bssid not in self.bssids_associated_with_ssids:
        # If no ssid is known, use the ssid name "unknown_ssid_80:21:46:af:28:66"
        missing_ssid_name = 'unknown_ssid_{}'.format(bssid)
        if missing_ssid_name in self.ssid_to_access_point:
            self.ssid_to_access_point[missing_ssid_name] |= {bssid}
        else:
            self.ssid_to_access_point[missing_ssid_name] = {bssid}

    if frame.signal_strength:
        ap_node['signal'] = frame.signal_strength

    # Only associate with channels and devices for data packets since, for example, APs
    # send beacons on channels that they don't actually communicate on.
    if frame.frame_type() == dot11_frame.Dot11Frame.DOT11_FRAME_TYPE_DATA:
        ap_node['devices'] |= (frame.macs - MACS_TO_IGNORE - {bssid})
        ap_node['channels'] |= {frame.channel}

    ap_node['frames'].append((time.time(), frame.frame_bytes))

    # Trim old frames (those that are older than window)
    self.frame_count_by_device[bssid] += 1
    if self.frame_count_by_device[bssid] % self.trim_every_num_frames == 0:
        ap_node['frames'] = trim_frames_to_window(ap_node['frames'], self.window)

def update_device(self, mac, frame):
    if mac in MACS_TO_IGNORE:
        return

    if mac not in self.devices:
        dev_node = {'vendor': self.mac_vendor_db.lookup(mac),
                    'signal': frame.signal_strength,
                    'frames_in': [],
                    'frames_out': []}
        self.devices[mac] = dev_node
    else:
        dev_node = self.devices[mac]

    dev_node['signal'] = frame.signal_strength

    if mac == frame.src:
        dev_node['frames_out'].append((time.time(), frame.frame_bytes))
    elif mac == frame.dst:
        dev_node['frames_in'].append((time.time(), frame.frame_bytes))

    # Trim old frames (those that are older than window)
    self.frame_count_by_device[mac] += 1
    if self.frame_count_by_device[mac] % self.trim_every_num_frames == 0:
        dev_node['frames_out'] = trim_frames_to_window(dev_node['frames_out'], self.window)
        dev_node['frames_in'] = trim_frames_to_window(dev_node['frames_in'], self.window)

def lookup(self, mac):
    """MAC -> Manufacturer ('48:AD:08:AA:BB:CC' -> 'HUAWEI TECHNOLOGIES CO.,LTD')"""
    try:
        oui_prefix = mac.upper().replace(':', '')[0:6]
        if oui_prefix in self.db:
            return self.db[oui_prefix]
    except Exception:
        pass

    return ''

def frame_type_name(self):
    """Returns the type of frame - 'management', 'control', 'data', or 'unknown'."""
    if self.frame.type == self.DOT11_FRAME_TYPE_MANAGEMENT:
        return 'management'
    elif self.frame.type == self.DOT11_FRAME_TYPE_CONTROL:
        return 'control'
    elif self.frame.type == self.DOT11_FRAME_TYPE_DATA:
        return 'data'
    return 'unknown'

def __str__(self):
    return 'Dot11 (type={}, from={}, to={}, bssid={}, ssid={}, signal_strength={})'.format(
        self.frame_type_name(), self.src, self.dst, self.bssid, self.ssid, self.signal_strength)

def stop(self):
    self.iface_manager.stop()

    if self.do_map:
        # Flush map to disk
        self.dot11_map.save_to_file(self.map_file)

def process_packet(self, pkt):
    if pkt.haslayer(scapy.Dot11):
        looking_for_specifics_and_none_found = self.aps_to_watch_set or self.devices_to_watch_set
        frame = dot11_frame.Dot11Frame(pkt, int(self.iface_manager.current_channel), iface=self.iface_manager.iface)
        if self.do_map:
            self.log_newly_found(frame)

        if self.display_all_packets:
            print('\t', pkt.summary())

        # See if any APs we care about (if we're looking for specific APs)
        if self.aps_to_watch_set:
            if frame.bssid not in self.aps_to_watch_set:
                looking_for_specifics_and_none_found = False

        # See if any MACs we care about (if we're looking for specific MACs)
        if self.devices_to_watch_set:
            matched_macs = self.devices_to_watch_set & frame.macs
            if matched_macs:
                looking_for_specifics_and_none_found = False

                # Display matched packets (if specified)
                if self.display_matching_packets and not self.display_all_packets:
                    print('\t', pkt.summary())

        # If we are looking for specific APs or Devices and none are found, no further processing needed
        if looking_for_specifics_and_none_found:
            return

        # If map mode enabled, do it. Note that we don't exclude non-matching MACs from the mapping
        # (which is why this isn't under the 'if matched_matcs' block).
        # Note: we update the map whether do_map is true or false since it's used for tracking; just don't save map
        self.dot11_map.add_frame(frame)
        if self.do_map:
            if time.time() - self.map_last_save >= self.map_save_interval:
                self.dot11_map.save_to_file(self.map_file)
                self.map_last_save = time.time()

        if self.do_track:
            self.dot11_tracker.add_frame(frame, pkt)

        # Update device tracking (for traffic-based)
        self.iface_manager.add_frame(frame)

def start(self):
    self.logger.debug('Starting monitoring on %s', self.iface_manager.iface)
    self.iface_manager.start()
    while True:
        try:
            # macOS
            if platform.system() == 'Darwin':
                self.logger.warning('trackerjacker macOS support is pre-alpha - most functionality is linux-only')
                scapy.sniff(iface=self.iface_manager.iface, monitor=True, prn=self.process_packet, store=0)
                break
            # linux
            else:
                # For versions of scapy that don't provide the exceptions kwarg
                scapy.sniff(iface=self.iface_manager.iface, prn=self.process_packet, store=0)
                break

        except TJException:
            raise
        except (OSError, IOError):
            self.logger.error(traceback.format_exc())
            self.logger.info('Sniffer error occurred. Restarting sniffer in 3 seconds...')
            time.sleep(3)

def do_simple_tasks_if_specified(args):
    if args.version:
        from .version import __version__
        print('trackerjacker {}'.format(__version__))
        sys.exit(0)
    elif args.do_enable_monitor_mode:
        if not args.iface:
            raise TJException('You must specify the interface with the -i paramter')
        device_management.monitor_mode_on(args.iface)
        print('Enabled monitor mode on {}'.format(args.iface))
        sys.exit(0)
    elif args.do_disable_monitor_mode:
        if not args.iface:
            raise TJException('You must specify the interface with the -i paramter')
        device_management.monitor_mode_off(args.iface)
        print('Disabled monitor mode on {}'.format(args.iface))
        sys.exit(0)
    elif args.mac_lookup:
        vendor = ieee_mac_vendor_db.MacVendorDB().lookup(args.mac_lookup)
        if vendor:
            print(vendor)
        else:
            print('Vendor for {} not found'.format(args.mac_lookup), file=sys.stderr)
        sys.exit(0)
    elif args.print_default_config:
        print(json.dumps(config_management.DEFAULT_CONFIG, indent=4, sort_keys=True))
        sys.exit(0)
    elif args.set_channel:
        if not args.iface:
            raise TJException('You must specify the interface with the -i paramter')
        channel = args.set_channel[0]
        device_management.switch_to_channel(args.iface, channel)
        print('Set channel to {} on {}'.format(channel, args.iface))
        sys.exit(0)

def main():
    if not os.getuid() == 0:
        print('trackerjacker requires r00t!', file=sys.stderr)
        sys.exit(errno.EPERM)

    argparse_args = config_management.get_arg_parser().parse_args()

    # Some command-line args specify to just perform a simple task and then exit
    try:
        do_simple_tasks_if_specified(argparse_args)
    except TJException as e:
        print('Error: {}'.format(e), file=sys.stderr)
        sys.exit(1)

    try:
        config = config_management.build_config(argparse_args)
    except TJException as e:
        print('{}'.format(e))
        sys.exit(1)

    if config['log_level'] == 'DEBUG':
        print('Config:')
        pprint.pprint(config)

    # Setup logger
    logger = make_logger(config.pop('log_path'), config.pop('log_level'))

    try:
        tj = TrackerJacker(**dict(config, **{'logger': logger}))  # pylint: disable=E1123
        tj.start()
    except TJException as e:
        logger.critical('Error: %s', e)
    except KeyboardInterrupt:
        print('Stopping...')
    finally:
        try:
            tj.stop()
        except UnboundLocalError:
            # Exception was thrown in TrackerJacker initializer, so 'tj' doesn't exist
            pass
